const skillPills = document.querySelector('#skill-pills');
const skillTabs = [...document.querySelectorAll('.skill-tab')];
function showSkills(name) {
  const visible = skills[name] || skills.core;
  skillPills.innerHTML = visible.map(([label, color]) => `<span class="skill-chip" style="--chip:${color}"><i aria-hidden="true"></i>${label}</span>`).join('');
  skillTabs.forEach((tab) => {
    const selected = tab.dataset.skill === name;
    tab.classList.toggle('active', selected);
    tab.setAttribute('aria-selected', String(selected));
  });
}
skillTabs.forEach((tab) => tab.addEventListener('click', () => showSkills(tab.dataset.skill)));
showSkills('all');

