const pixelButton = document.querySelector('#pixel-button');
const pixelGuest = document.querySelector('#pixel-guest');
const bubble = document.querySelector('#speech-bubble');
pixelButton.addEventListener('click', () => {
  const open = window.matchMedia('(hover: hover)').matches ? true : !bubble.classList.contains('is-visible');
  bubble.classList.toggle('is-visible', open);
  pixelGuest.classList.toggle('is-talking', open);
  pixelButton.setAttribute('aria-label', open ? 'Close pixel character message' : 'Click the pixel character');
});
document.addEventListener('click', (event) => {
  if (!pixelGuest.contains(event.target)) {
    bubble.classList.remove('is-visible');
    pixelGuest.classList.remove('is-talking');
    pixelButton.setAttribute('aria-label', 'Click the pixel character');
  }
});

function setPixelMessage(open) {
  bubble.classList.toggle('is-visible', open);
  pixelGuest.classList.toggle('is-talking', open);
  pixelButton.setAttribute('aria-expanded', String(open));
}
pixelButton.addEventListener('pointerenter', (event) => { if (event.pointerType !== 'touch') setPixelMessage(true); });
pixelGuest.addEventListener('pointerleave', (event) => { if (event.pointerType !== 'touch') setPixelMessage(false); });
pixelButton.addEventListener('focus', () => { if (pixelButton.matches(':focus-visible')) setPixelMessage(true); });
pixelButton.addEventListener('blur', () => setPixelMessage(false));

const dockItems = [...document.querySelectorAll('.dock-item')];
const navTargets = [...document.querySelectorAll('#hero, #about, #experience, #projects, #contact')];
const activeObserver = new IntersectionObserver((entries) => {
  const active = entries.filter((entry) => entry.isIntersecting).sort((a, b) => b.intersectionRatio - a.intersectionRatio)[0];
  if (!active) return;
  dockItems.forEach((item) => item.classList.toggle('active', item.dataset.section === active.target.id));
}, { rootMargin: '-39% 0px -45% 0px', threshold: [0, .1, .2, .4, .65] });
navTargets.forEach((section) => activeObserver.observe(section));

const form = document.querySelector('#contact-form');
const contactTrap = document.createElement('input');
contactTrap.type = 'text';
contactTrap.name = '_honey';
contactTrap.tabIndex = -1;
contactTrap.autocomplete = 'off';
contactTrap.setAttribute('aria-hidden', 'true');
contactTrap.style.display = 'none';
form.append(contactTrap);
form.elements.name.maxLength = 100;
form.elements.email.maxLength = 254;
form.elements.message.maxLength = 5000;
let contactSending = false;
form.addEventListener('submit', async (event) => {
  event.preventDefault();
  if (contactSending || !form.reportValidity()) return;
  const status = document.querySelector('#form-status');
  if (contactTrap.value) return;
  const values = new FormData(form);
  const button = form.querySelector('button[type="submit"]');
  const buttonContent = button.innerHTML;
  contactSending = true;
  button.disabled = true;
  button.textContent = 'Sending…';
  form.setAttribute('aria-busy', 'true');
  status.hidden = false;
  status.textContent = 'Sending your message…';
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 20000);
  try {
    const response = await fetch('https://formsubmit.co/ajax/talhaarikyatirim@gmail.com', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
      body: JSON.stringify({
        name: String(values.get('name')).trim(),
        email: String(values.get('email')).trim(),
        message: String(values.get('message')).trim(),
        _replyto: String(values.get('email')).trim(),
        _subject: 'New portfolio message — ' + String(values.get('name')).trim(),
        _template: 'table',
        _honey: ''
      }),
      signal: controller.signal
    });
    const result = await response.json();
    if (!response.ok || !(result.success === true || result.success === 'true')) throw new Error('Submission failed');
    status.textContent = 'Thank you! Your message has been submitted. I’ll get back to you soon.';
    form.reset();
  } catch (error) {
    status.replaceChildren(document.createTextNode('Your message could not be sent. Please try again or '));
    const fallback = document.createElement('a');
    fallback.href = 'mailto:talhaarikyatirim@gmail.com';
    fallback.textContent = 'email me directly';
    fallback.style.textDecoration = 'underline';
    status.append(fallback, document.createTextNode('.'));
  } finally {
    clearTimeout(timeout);
    contactSending = false;
    button.disabled = false;
    button.innerHTML = buttonContent;
    form.removeAttribute('aria-busy');
  }
});

const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
const canvas = document.querySelector('#world-canvas');
const context = canvas.getContext('2d');
let width = innerWidth, height = innerHeight, frame = 0, previous = 0;
let nightAmount = 0;
let pointerX = 0, pointerY = 0;
let manualLamp = false;
const root = document.documentElement;
const clamp = (value, min = 0, max = 1) => Math.max(min, Math.min(max, value));
function updateRoom() {
  const maxScroll = document.documentElement.scrollHeight - innerHeight;
  const progress = clamp(scrollY / Math.max(1, maxScroll));
  // Morning at the top, noon through About, sunset through Experience, night below.
  nightAmount = clamp((progress - .28) / .64);
  nightAmount = nightAmount * nightAmount * (3 - 2 * nightAmount);
  const sunset = Math.max(0, 1 - Math.abs(progress - .56) / .25) * .22;
  root.style.setProperty('--night', nightAmount.toFixed(3));
  root.style.setProperty('--noon-light', String(1 + Math.max(0, 1 - Math.abs(progress - .22) / .22) * .07));
  root.style.setProperty('--sunset', sunset.toFixed(3));
  root.style.setProperty('--room-y', `${-progress * 9}px`);
  root.style.setProperty('--lamp-strength', String(manualLamp ? 1 : clamp((nightAmount - .2) * 1.25)));
  document.body.dataset.time = progress < .16 ? 'morning' : progress < .4 ? 'noon' : progress < .76 ? 'evening' : 'night';
}
function resizeRoom() {
  width = innerWidth; height = innerHeight;
  const ratio = Math.min(devicePixelRatio || 1, 1.4);
  canvas.width = width * ratio; canvas.height = height * ratio;
  context.setTransform(ratio, 0, 0, ratio, 0, 0);
  updateRoom();
}
function drawRoom(time) {
  const interval = 50;
  if (time - previous >= interval) {
    previous = time;
    context.clearRect(0, 0, width, height);
    const count = 24;
    for (let i = 0; i < count; i++) {
      const x = ((i * .6180339) % 1) * width + Math.sin(time * .0002 + i) * 18;
      const y = (((i * .754877) % 1) * height - time * .007 + height * 100) % height;
      const alpha = (.1 + nightAmount * .16) * (.55 + .45 * Math.sin(time * .001 + i));
      context.fillStyle = `rgba(255,228,157,${alpha})`;
      context.fillRect(Math.round(x), Math.round(y), nightAmount > .5 ? 2 : 1, nightAmount > .5 ? 2 : 1);
    }
  }
  if (!reduceMotion.matches && !document.hidden) frame = requestAnimationFrame(drawRoom);
}
function startRoom() { cancelAnimationFrame(frame); context.clearRect(0,0,width,height); if (!reduceMotion.matches && !document.hidden) frame = requestAnimationFrame(drawRoom); }
let scrollFrame = 0;
window.addEventListener('scroll', () => { if (!scrollFrame) scrollFrame = requestAnimationFrame(() => { updateRoom(); scrollFrame = 0; }); }, {passive:true});
window.addEventListener('pointermove', event => {
  if (reduceMotion.matches || event.pointerType === 'touch') return;
  pointerX = (event.clientX / width - .5) * 5; pointerY = (event.clientY / height - .5) * 3;
  root.style.setProperty('--pointer-x', `${pointerX}px`); root.style.setProperty('--pointer-y', `${pointerY}px`);
}, {passive:true});
window.addEventListener('resize', resizeRoom, {passive:true});
document.addEventListener('visibilitychange', startRoom);
reduceMotion.addEventListener?.('change', startRoom);
document.querySelector('.hotspot-lamp').addEventListener('click', event => { manualLamp = !manualLamp; event.currentTarget.classList.toggle('is-on', manualLamp); updateRoom(); });
document.querySelectorAll('.room-hotspot').forEach(button => button.addEventListener('click', () => { button.classList.add('is-active'); setTimeout(() => button.classList.remove('is-active'), 2200); }));
resizeRoom(); startRoom();
// Resolve direct section links after dynamic timeline content has its final height.
window.addEventListener('load', () => {
  const sectionId = decodeURIComponent(location.hash.slice(1));
  if (!sectionId) return;
  const target = document.getElementById(sectionId);
  if (target) requestAnimationFrame(() => target.scrollIntoView({behavior:'instant', block:'start'}));
}, {once:true});

