ring.innerHTML=projects.map((p,i)=>`<button class="ring-card" data-project="${i}" aria-label="Show ${p.name}" style="--card-angle:${i*60}deg">${cover(p)}<div class="ring-card-copy"><h3>${p.name}</h3><p>${p.short}</p></div></button>`).join('');
const mobileProjects=window.matchMedia('(max-width:620px)');
