let mobileScrollTick=0;
mobileTrack.addEventListener('scroll',()=>{if(mobileScrollTick)return;mobileScrollTick=requestAnimationFrame(()=>{const cards=[...mobileTrack.children];const center=mobileTrack.scrollLeft+mobileTrack.clientWidth/2;let nearest=0,distance=Infinity;cards.forEach((card,i)=>{const d=Math.abs(card.getBoundingClientRect().left-mobileTrack.getBoundingClientRect().left+mobileTrack.scrollLeft+card.offsetWidth/2-center);if(d<distance){distance=d;nearest=i}});selectProject(nearest);mobileScrollTick=0;});},{passive:true});
document.querySelector('#project-dots').innerHTML=projects.map((p,i)=>`<button data-project="${i}" aria-label="Show ${p.name}"></button>`).join('');
function selectProject(i){if(i===activeProject)return;activeProject=i;const p=projects[i];info.innerHTML=`<div class="window-bar"><div class="window-controls" aria-hidden="true"><i></i><i></i><i></i></div><span>Project ${String(i+1).padStart(2,'0')} of 06</span></div><div class="project-info-body"><span class="project-status">${p.status}</span><h3>${p.name}</h3><p class="project-role">${p.role}</p><a class="project-link" href="${p.url}" target="_blank" rel="noopener noreferrer">${p.link} ↗</a><p class="project-description">${p.description}</p><div class="project-impact"><h4>Impact</h4><p>${p.impact}</p></div>${p.facts.length?`<div class="project-facts">${p.facts.map(f=>`<div><b>${f[0]}</b><span>${f[1]}</span></div>`).join('')}</div>`:''}<div class="project-tech" aria-label="Tools and disciplines">${p.tags.map(t=>`<span>${t}</span>`).join('')}</div></div>`;document.querySelectorAll('[data-project]').forEach(el=>{el.classList.toggle('is-selected',+el.dataset.project===i);el.setAttribute('aria-pressed',String(+el.dataset.project===i));});}
let projectTop=0,projectRange=1,ringPosition=0,ringTarget=0,ringFrame=0,ringTime=0,ringIdle=0;
function measureProjects(){projectTop=projectSection.offsetTop;projectRange=Math.max(1,projectSection.offsetHeight-innerHeight);}
function paintRing(){ring.style.setProperty('--ring-turn',`${-ringPosition*60}deg`);const candidate=Math.round(ringPosition);if(activeProject<0 || Math.abs(ringPosition-activeProject)>.54)selectProject(candidate);}
function animateRing(time){const dt=Math.min(50,ringTime?time-ringTime:16);ringTime=time;ringPosition+=(ringTarget-ringPosition)*(1-Math.exp(-dt/80));if(Math.abs(ringPosition-ringTarget)<.0002)ringPosition=ringTarget;paintRing();if(ringPosition!==ringTarget)ringFrame=requestAnimationFrame(animateRing);else{ringFrame=0;ringTime=0;}}
function startRing(){if(reduceMotion.matches){ringPosition=Math.round(ringTarget);paintRing();return;}if(!ringFrame)ringFrame=requestAnimationFrame(animateRing);}
function updateProjects(){if(mobileProjects.matches){if(activeProject<0){ringPosition=0;ringTarget=0;paintRing();}return;}ringTarget=Math.max(0,Math.min(1,(scrollY-projectTop)/projectRange))*5;startRing();clearTimeout(ringIdle);ringIdle=setTimeout(()=>{ringTarget=Math.round(ringTarget);startRing();},160);}
mobileProjects.addEventListener('change',()=>{activeProject=-1;measureProjects();updateProjects();});
measureProjects();window.addEventListener('load',()=>{measureProjects();updateProjects();});
function goProject(i){i=Math.max(0,Math.min(5,i));if(mobileProjects.matches){ringScroller.scrollTo({left:i*ringScroller.clientWidth,behavior:reduceMotion.matches?'instant':'smooth'});return;}window.scrollTo({top:projectSection.offsetTop+i/5*(projectSection.offsetHeight-innerHeight),behavior:'instant'});}
document.querySelectorAll('[data-project]').forEach(el=>el.addEventListener('click',()=>goProject(+el.dataset.project)));

let projectTick=false;window.addEventListener('scroll',()=>{if(!projectTick){requestAnimationFrame(()=>{updateProjects();projectTick=false});projectTick=true}},{passive:true});window.addEventListener('resize',()=>{measureProjects();updateProjects();});updateProjects();

// Native horizontal scrolling handles touch inertia and snapping on phones.
const mobileRingSurface=document.querySelector('.project-perspective');
const ringScroller=document.createElement('div');
ringScroller.className='mobile-ring-scroll';
ringScroller.setAttribute('role','region');
ringScroller.setAttribute('aria-label','Swipe left or right to change project');
ringScroller.tabIndex=0;
ringScroller.innerHTML=projects.map(()=>'<span aria-hidden="true"></span>').join('');
mobileRingSurface.append(ringScroller);
let ringScrollFrame=0;
ringScroller.addEventListener('scroll',()=>{if(!mobileProjects.matches||ringScrollFrame)return;ringScrollFrame=requestAnimationFrame(()=>{cancelAnimationFrame(ringFrame);ringFrame=0;ringTime=0;ringPosition=Math.max(0,Math.min(5,ringScroller.scrollLeft/Math.max(1,ringScroller.clientWidth)));ringTarget=ringPosition;ring.style.setProperty('--ring-turn',`${-ringPosition*60}deg`);selectProject(Math.round(ringPosition));ringScrollFrame=0;});},{passive:true});
ringScroller.addEventListener('keydown',event=>{if(event.key==='ArrowRight'||event.key==='ArrowLeft'){event.preventDefault();goProject(activeProject+(event.key==='ArrowRight'?1:-1));}});
